import React, { MouseEventHandler, PropsWithChildren } from "react";
import clsx from "clsx";
import { Toast as ToastStyles } from "@airbus/styles";
import { Close as CloseIcon } from "@airbus/icons/react";
import useTimeout from "../../lib/hooks/useTimeout";
import { createUseStyles } from "../../lib/styling";
import IconButton from "../IconButton";
import { CommonProps } from "../helperTypes";

const useStyles = createUseStyles(ToastStyles, "toast");

type Variants = "info" | "success" | "warning" | "error";

type Props = PropsWithChildren<{
  /** Show close icon button */
  allowClose?: boolean;
  /** Delay in milliseconds to hide notification */
  autoHideDuration?: number;
  /** Inline mode with larger size */
  inline?: boolean;
  onClick?: MouseEventHandler<HTMLDivElement>;
  onMouseDown?: MouseEventHandler<HTMLDivElement>;
  /** Called when user closes notification, or after `autoHideDuration` */
  onClose?: () => void;
  /** Time of the notification */
  time?: string;
  /** Title of the notification */
  title?: string;
  /**
   * The variant of the chip.
   * @default info
   */
  variant?: Variants;
}>;

export type ToastProps = Props & CommonProps;

const Toast = (props: ToastProps) => {
  const {
    allowClose,
    autoHideDuration,
    children,
    className,
    inline,
    onClose,
    time,
    title,
    variant,
    ...rest
  } = props;
  const classes = useStyles();

  const handleClose = () => onClose && onClose();
  useTimeout(handleClose, autoHideDuration);

  return (
    <div
      className={clsx(classes.root, className, {
        [classes._error]: variant === "error",
        [classes._success]: variant === "success",
        [classes._warning]: variant === "warning",
        [classes._info]: variant === "info",
        [classes._inline]: inline === true,
        [classes._withRemove]: allowClose,
      })}
      role={variant === "error" || variant === "warning" ? "alert" : "status"}
      {...rest}
    >
      {(title || time) && (
        <div className={clsx(classes.header)}>
          {title && <div className={classes.heading}>{title}</div>}
          {time && <div className={classes.time}>{time}</div>}
        </div>
      )}
      {children}
      {allowClose && (
        <IconButton
          aria-label="Remove"
          className={classes.removeBtn}
          size="small"
          variant="ghost"
          onClick={handleClose}
          onTouchEnd={(e: any) => {
            e.preventDefault();
            handleClose();
          }}
          onMouseDown={(e) => {
            e.preventDefault();
            e.stopPropagation();
          }}
        >
          <CloseIcon />
        </IconButton>
      )}
    </div>
  );
};

export default Toast;
